  "longest-common-prefix": { python: "class Solution:\r\n    def longestCommonPrefix(self, strs: List[str]) -> str:\r\n        for i in range(len(strs[0])):\r\n            for s in strs[1:]:\r\n                if len(s) <= i or s[i] != strs[0][i]:\r\n                    return s[:i]\r\n        return strs[0]", java: "class Solution {\r\n    public String longestCommonPrefix(String[] strs) {\r\n        if (strs == null || strs.length == 0) return \"\";\r\n\r\n        String prefix = strs[0]; // 设定第一个字符串为初始公共前缀\r\n\r\n        for (int i = 1; i < strs.length; i++) {\r\n            // 如果当前字符串不是以 prefix 开头，就缩短 prefix\r\n            while (!strs[i].startsWith(prefix)) {\r\n                prefix = prefix.substring(0, prefix.length() - 1);\r\n                if (prefix.isEmpty()) return \"\";\r\n            }\r\n        }\r\n\r\n        return prefix;\r\n    }\r\n}\r\n" },
  "longest-substring-without-repeating-characters": { python: "class Solution:\r\n    def lengthOfLongestSubstring(self, s: str) -> int:\r\n        ss = set()\r\n        ans = i = 0\r\n        for j, c in enumerate(s):\r\n            while c in ss:\r\n                ss.remove(s[i])\r\n                i += 1\r\n            ss.add(c)\r\n            ans = max(ans, j - i + 1)\r\n        return ans", java: "class Solution {\r\n    public int lengthOfLongestSubstring(String s) {\r\n        Map<Character, Integer> map = new HashMap<>();\r\n        int left = 0, ans = 0;\r\n\r\n        for (int right = 0; right < s.length(); right++) {\r\n            char c = s.charAt(right);\r\n\r\n            // 如果字符 c 出现过，并且在当前窗口内\r\n            if (map.containsKey(c) && map.get(c) >= left) {\r\n                left = map.get(c) + 1;  // 把 left 移动到重复字符之后\r\n            }\r\n\r\n            map.put(c, right);  // 更新字符 c 的最新位置\r\n            ans = Math.max(ans, right - left + 1);\r\n        }\r\n\r\n        return ans;\r\n    }\r\n}" },
