  "merge-sorted-array": { python: "class Solution:\r\n    def merge(self, nums1: List[int], m: int, nums2: List[int], n: int) -> None:\r\n        k = m + n - 1\r\n        i, j = m - 1, n - 1\r\n        while j >= 0:\r\n            if i >= 0 and nums1[i] > nums2[j]:\r\n                nums1[k] = nums1[i]\r\n                i -= 1\r\n            else:\r\n                nums1[k] = nums2[j]\r\n                j -= 1\r\n            k -= 1", java: "class Solution {\r\n    public void merge(int[] nums1, int m, int[] nums2, int n) {\r\n        int i = m - 1;\r\n        int j = n - 1;\r\n        int k = m + n - 1;\r\n        // 将nums1和nums2中比较大的数，复制到nums1的末尾\r\n        while (i >= 0 && j >= 0) {\r\n            if (nums1[i] >= nums2[j]) {\r\n                nums1[k--] = nums1[i--];\r\n            } else {\r\n                nums1[k--] = nums2[j--];\r\n            }\r\n        }\r\n        // 如果数组2中还有剩余元素，复制到nums1中\r\n        // 如果数组2中没有元素了，但数组1中还有，那无需操作\r\n        while (j >= 0) {\r\n            nums1[k--] = nums2[j--];\r\n        }\r\n    }\r\n}" },
  "move-zeroes": { python: "class Solution:\r\n    def moveZeroes(self, nums: List[int]) -> None:\r\n        i = -1\r\n        for j, x in enumerate(nums):\r\n            if x:\r\n                i += 1\r\n                nums[i], nums[j] = nums[j], nums[i]", java: "class Solution {\r\n    public void moveZeroes(int[] nums) {\r\n        int i = -1, n = nums.length;\r\n        for (int j = 0; j < n; ++j) {\r\n            if (nums[j] != 0) {\r\n                int t = nums[++i];\r\n                nums[i] = nums[j];\r\n                nums[j] = t;\r\n            }\r\n        }\r\n    }\r\n}" },
  "next-permutation": { python: "class Solution:\r\n    def nextPermutation(self, nums: List[int]) -> None:\r\n        n = len(nums)\r\n        i = next((i for i in range(n - 2, -1, -1) if nums[i] < nums[i + 1]), -1)\r\n        if ~i:\r\n            j = next((j for j in range(n - 1, i, -1) if nums[j] > nums[i]))\r\n            nums[i], nums[j] = nums[j], nums[i]\r\n        nums[i + 1 :] = nums[i + 1 :][::-1]", java: "class Solution {\r\n    public void nextPermutation(int[] nums) {\r\n        int n = nums.length;\r\n        int i = n - 2;\r\n        for (; i >= 0; --i) {\r\n            if (nums[i] < nums[i + 1]) {\r\n                break;\r\n            }\r\n        }\r\n        if (i >= 0) {\r\n            for (int j = n - 1; j > i; --j) {\r\n                if (nums[j] > nums[i]) {\r\n                    swap(nums, i, j);\r\n                    break;\r\n                }\r\n            }\r\n        }\r\n\r\n        for (int j = i + 1, k = n - 1; j < k; ++j, --k) {\r\n            swap(nums, j, k);\r\n        }\r\n    }\r\n\r\n    private void swap(int[] nums, int i, int j) {\r\n        int t = nums[j];\r\n        nums[j] = nums[i];\r\n        nums[i] = t;\r\n    }\r\n}" },
